import fs from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

type Confidence = { value: string | null; confidence: number };
type Extraction = { id: string; document_id: string; fields: Record<string, Confidence> };
type QueueItem = {
  vendor_id: string;
  vendor_name: string;
  lowest_confidence: number;
  extractions: Extraction[];
};

const DOCUMENTS = [
  { kind: "w9", file: "w9.pdf" },
  { kind: "insurance_certificate", file: "insurance_certificate.pdf" },
  { kind: "contract", file: "contract.pdf" },
] as const;

const CONTENT_TYPES: Record<string, string> = {
  pdf: "application/pdf",
};

async function waitForExtracted(
  request: import("@playwright/test").APIRequestContext,
  documentId: string,
): Promise<void> {
  for (let attempt = 0; attempt < 60; attempt++) {
    const response = await request.get(`/api/documents/${documentId}`);
    expect(response.status()).toBe(200);
    const doc = (await response.json()) as { status: string };
    if (doc.status === "extracted") return;
    expect(doc.status, "document must not fail extraction").not.toBe("failed");
    await new Promise((r) => setTimeout(r, 1000));
  }
  throw new Error(`document ${documentId} did not finish extraction`);
}

async function createReviewedVendor(
  member: import("@playwright/test").APIRequestContext,
  name: string,
): Promise<{ vendorId: string; lowest: number }> {
  const created = await member.post("/api/vendors", {
    data: { name, category: "services", contact_email: "ops@northwind.test" },
  });
  expect(created.status()).toBe(201);
  const vendorId = ((await created.json()) as { id: string }).id;

  const documentIds: string[] = [];
  for (const doc of DOCUMENTS) {
    const upload = await member.post(`/api/vendors/${vendorId}/documents`, {
      multipart: {
        kind: doc.kind,
        file: {
          name: doc.file,
          mimeType: CONTENT_TYPES.pdf,
          buffer: fs.readFileSync(sample(doc.file)),
        },
      },
    });
    expect(upload.status()).toBe(201);
    documentIds.push(((await upload.json()) as { id: string }).id);
  }

  for (const documentId of documentIds) {
    await waitForExtracted(member, documentId);
  }

  const submit = await member.post(`/api/vendors/${vendorId}/submit`);
  expect(submit.status()).toBe(200);

  let lowest = Number.POSITIVE_INFINITY;
  for (const documentId of documentIds) {
    const res = await member.get(`/api/documents/${documentId}/extraction`);
    expect(res.status()).toBe(200);
    const extraction = (await res.json()) as Extraction;
    for (const field of Object.values(extraction.fields)) {
      lowest = Math.min(lowest, field.confidence);
    }
  }
  return { vendorId, lowest };
}

test.describe("review queue ordering", () => {
  test(
    "the review queue lists lowest confidence first",
    { tag: "@REV-03" },
    async ({ apiAs }) => {
      // Arrange: two vendors in review, created by a member of the same tenant.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");
      const first = await createReviewedVendor(member, uniqueName("Queue Vendor A"));
      const second = await createReviewedVendor(member, uniqueName("Queue Vendor B"));

      // Act
      const response = await reviewer.get("/api/review-queue");

      // Assert
      expect(response.status()).toBe(200);
      const queue = (await response.json()) as QueueItem[];

      // The queue is shared across parallel tests, so check ordering invariants
      // over the whole list and the relative position of the two vendors.
      for (let i = 0; i + 1 < queue.length; i++) {
        expect(queue[i].lowest_confidence).toBeLessThanOrEqual(
          queue[i + 1].lowest_confidence,
        );
      }

      const indexOf = (vendorId: string) =>
        queue.findIndex((item) => item.vendor_id === vendorId);
      const indexA = indexOf(first.vendorId);
      const indexB = indexOf(second.vendorId);
      expect(indexA).toBeGreaterThanOrEqual(0);
      expect(indexB).toBeGreaterThanOrEqual(0);

      const lowerFirst = first.lowest <= second.lowest ? indexA : indexB;
      const higherFirst = first.lowest <= second.lowest ? indexB : indexA;
      expect(lowerFirst).toBeLessThan(higherFirst);

      // Each item's lowest_confidence matches the minimum field confidence it carries.
      for (const item of [queue[indexA], queue[indexB]]) {
        const minField = Math.min(
          ...item.extractions.flatMap((e) =>
            Object.values(e.fields).map((f) => f.confidence),
          ),
        );
        expect(item.lowest_confidence).toBeCloseTo(minField, 5);
      }
    },
  );
});
